# "Totally Raotional" History S01E08 "The Great Leap Backwards" (Topic: Mao's China)
# Format and helpers: see common.py; check with lint_episode.py.
# SENSITIVE: comedy only from Dad's household campaign. Nobody impersonates Mao. Land-reform violence,
# the Great Famine and Cultural Revolution persecution are inside serious(). Neutral on present-day China.

EP = dict(topic="mao-china", logline="Dad launches a household 'Great Leap Forward', melts Mum's woks into 'art' and reports fake results. Chrono explains China 1839-1976: humiliation, revolution, the Long March, 1949, the Great Leap Forward and famine, the Cultural Revolution.")

# ---------------- COLD OPEN ----------------
scene("living", [("tara", 300), ("dad", 760)])
L("dad", "Family! I am launching a campaign. The Great Leap Forward of the Rao household!", mood="excited", shot="close", prop="placard")
L("tara", "Dad. Do you know what the Great Leap Forward was?", mood="deadpan", shot="close")
L("dad", "A leap. Forward. It's in the name.", mood="smug", shot="close", gap=0.3)
scene("living", [("tara", 260), ("mum", 600), ("dad", 980)])
L("dad", "In fifteen days, we overtake the Tans next door. In everything.", mood="determined", shot="close", boardClear=True, board="TARGET: overtake the Tans in 15 days!")
L("dad", "Mr Tan waved at me. Smugly. Phase one. Melt our old woks into a sculpture. A backyard furnace!", mood="smug", shot="close")
L("mum", "We live on the fourteenth floor. We don't have a backyard.", mood="deadpan", shot="close")
L("dad", "The community club has a kiln. With goggles. Very safe.", mood="smug", shot="close")
L("mum", "Not my good wok.", mood="annoyed", shot="close")
L("dad", "Define good.", mood="smug", shot="close")
freeze("“DEFINE GOOD.”", 2.4, narrator="Narrator: It was her good wok.")
confess("tara", "TARA RAO · 12 · Has Read Ahead In The Textbook")
L("tara", "My dad named his project after one of the worst disasters of the twentieth century. He thinks it's a slogan.", mood="deadpan")
L("tara", "I need an hourglass.", mood="deadpan", gap=0.6)

title()

# ---------------- ACT 1: CHINA IN CRISIS, THE COMMUNISTS RISE ----------------
scene("kitchen", [("tara", 380)])
L("tara", "Chrono. Dad has launched a Great Leap Forward.", mood="worried", shot="wide")
sfx("drawer")
poof("chrono", 860)
L("chrono", "Where are the woks? Never mind. To understand Mao, start before Mao.", mood="annoyed", shot="close")
L("chrono", "Eighteen thirty nine. Britain wins the Opium War, forcing opium and unequal treaties on China. Hong Kong goes to Britain.", mood="teach", shot="close", boardClear=True, board="1839–42  Opium War → unequal treaties")
L("chrono", "Foreign powers grab ports. The century of humiliation begins.", mood="teach", shot="close", board="the 'century of humiliation'")
L("chrono", "Nineteen eleven. A revolution ends the Qing dynasty, and over two thousand years of emperors. Sun Yat-sen leads the new Republic.", mood="teach", shot="close", board="1911  Qing falls · Sun Yat-sen")
L("tara", "Sun Yat-sen came to Singapore, didn't he?", mood="thinking", shot="close")
L("chrono", "Several times. His supporters' villa in Balestier is now a memorial hall.", mood="happy", shot="close")
L("chrono", "But the Republic fell apart. From nineteen sixteen, generals called warlords carved China up.", mood="teach", shot="close", board="1916–28  warlord era")
L("chrono", "Two rivals promised to save China. Chiang Kai-shek's Nationalists, the Guomindang. And the Communist Party, founded in nineteen twenty one.", mood="teach", shot="close", boardClear=True, board="GMD (Chiang Kai-shek)  vs  CCP (1921)")
L("chrono", "In nineteen twenty seven, Chiang turned on his Communist allies in Shanghai. Thousands were killed.", mood="serious", shot="close", board="1927  Shanghai Massacre")
L("chrono", "A Communist called Mao Zedong saw that China was a land of peasants. Win the countryside first.", mood="teach", shot="close", board="Mao: revolution through the PEASANTS")
L("chrono", "Nineteen thirty four. Chiang's armies surround the Communists in Jiangxi. They escape. The Long March.", mood="teach", shot="close", boardClear=True, board="1934–35  The Long March")
L("chrono", "Around ten thousand kilometres in a year. Only about one in ten who set out arrived.", mood="teach", shot="close", board="~10,000 km · about 1 in 10 arrived")
L("chrono", "Mao emerged as leader. The march became a legend, though some heroic stories were probably exaggerated. Check your sources.", mood="teach", shot="close", board="Mao rises to lead · base at Yan'an")

confess("dad", "VIKRAM RAO · Dad · Minister Of Household Productivity")
L("dad", "Update. Four woks collected. Two frying pans. And the barbecue tongs.", mood="smug")
L("dad", "Mum has not been informed. Need to know basis.", mood="smug", gap=0.6)

# ---------------- ACT 2: WAR, 1949 AND THE NEW CHINA ----------------
card("MEANWHILE, AT THE NATIONAL MUSEUM", "Tara and Mum. Dad is 'at the kiln'.", 2.4)
scene("museum", [("mum", 300), ("tara", 620)])
L("mum", "This gallery is about Japan's occupation of Singapore.", mood="serious", shot="close")
L("tara", "Japan invaded China first. Full-scale war from nineteen thirty seven.", mood="thinking", shot="close")
poof("chrono", 960)
L("chrono", "The invasion forced the two parties into a second United Front. On paper.", mood="teach", shot="close", boardClear=True, board="1937  Japan invades · 2nd United Front")
L("chrono", "Chiang's armies took the heaviest blows. Mao's guerrillas grew, giving landlords' land to peasants.", mood="teach", shot="close", board="CCP land reform → peasant support")
L("chrono", "The Nationalists were corrupt, and prices ran wild. Civil war returned in nineteen forty six.", mood="teach", shot="close", board="GMD: corruption, inflation · war 1946–49")
L("chrono", "On the first of October, nineteen forty nine, Mao proclaimed the People's Republic of China. Chiang retreated to Taiwan.", mood="teach", shot="close", boardClear=True, board="1 Oct 1949  People's Republic of China")
L("tara", "Crisis, a corrupt government, and a leader with peasant support.", mood="determined", shot="close")
L("chrono", "Same recipe as Germany. Different ingredients.", mood="happy", shot="close", gap=0.4)

scene("hawker", [("tara", 300), ("mum", 560), ("chrono", 780), ("uncle", 1000)])
L("uncle", "Museum, then dosa. Who is the sand clock?", mood="thinking", shot="close")
L("chrono", "A historian. Mao built a one party state. From nineteen fifty three, a Five Year Plan built Soviet-style industry.", mood="teach", shot="close", boardClear=True, board="1953–57  First Five-Year Plan")
L("chrono", "In nineteen fifty six, Mao said, let a hundred flowers bloom. Criticise the Party. People did.", mood="teach", shot="close", board="1956–57  Hundred Flowers")
L("chrono", "Then the Anti-Rightist Campaign. Hundreds of thousands of critics were punished, many in labour camps.", mood="serious", shot="close", board="1957  Anti-Rightist Campaign")
serious()
L("chrono", "Land reform had a darker side too. Landlords were denounced at mass meetings. Historians estimate hundreds of thousands were killed, possibly far more.", mood="serious", shot="close")
L("uncle", "So the lesson was, don't speak up.", mood="serious", shot="close")
L("chrono", "In a dictatorship, speaking up can cost everything.", mood="serious", shot="close", gap=1.0)
serious(False)

# ---------------- ACT 3: THE GREAT LEAP FORWARD, FAMINE, CULTURAL REVOLUTION ----------------
card("THAT EVENING", "Woks remaining: zero", 2.2)
scene("living", [("tara", 260), ("dad", 600), ("mum", 940)])
L("dad", "Progress report! Plants repotted, forty! Recycling, up five hundred percent! We have overtaken the Tans!", mood="excited", shot="close", prop="tablet", boardClear=True, board="Dad's report: 40 plants · recycling +500%")
L("mum", "We have two plants. One is plastic.", mood="deadpan", shot="close")
L("dad", "And the sculpture. It's called Progress.", mood="smug", shot="close")
L("mum", "That's my good wok. It's a lump.", mood="annoyed", shot="close")
freeze("“PROGRESS”", 2.4, narrator="Narrator: It was a lump.")
poof("chrono", 760)
L("chrono", "Sit down. The real Great Leap Forward was no joke.", mood="serious", shot="wide")
L("chrono", "Nineteen fifty eight. Mao wanted to overtake Britain's steel output within fifteen years. Peasants were moved into giant communes.", mood="teach", shot="close", boardClear=True, board="1958  Great Leap Forward · communes")
L("chrono", "Villages built backyard furnaces. People melted pots, pans, even farm tools. Most of the iron was useless.", mood="teach", shot="close", board="Backyard furnaces → useless iron")
L("chrono", "Officials, afraid of punishment, reported impossible harvests. The state took grain based on those figures. Far too much.", mood="teach", shot="close", board="False harvest reports → grain taken")
L("dad", "Like reporting forty plants when there are two.", mood="worried", shot="close")
serious()
L("chrono", "What followed was one of the deadliest famines in history.", mood="serious", shot="close")
L("chrono", "From nineteen fifty nine to sixty one, historians estimate fifteen to forty five million people died. Thirty million is often cited.", mood="serious", shot="close", boardClear=True, board="1959–61  Great Famine: est. 15–45 million")
L("chrono", "Most were farming families. Most historians conclude the main cause was policy, not just bad weather.", mood="serious", shot="close")
L("chrono", "When the defence minister, Peng Dehuai, warned Mao in nineteen fifty nine, Mao purged him. After that, few dared tell the truth.", mood="serious", shot="close", board="1959  Peng Dehuai purged for warning Mao")
L("tara", "So the lies kept going, because the truth was dangerous.", mood="sad", shot="close")
L("dad", "I'll tell Mum the real numbers.", mood="sad", shot="close", gap=1.2)
serious(False)
L("chrono", "Mao stepped back. Liu Shaoqi and Deng Xiaoping led a recovery. Mao wanted power back.", mood="teach", shot="close")
L("chrono", "In nineteen sixty six, he launched the Cultural Revolution. Millions of students became Red Guards, told to destroy the Four Olds.", mood="teach", shot="close", boardClear=True, board="1966–76  Cultural Revolution · Red Guards")
serious()
L("chrono", "Teachers, writers and officials were humiliated and attacked. Liu Shaoqi died in prison. Historians estimate hundreds of thousands, perhaps millions, died.", mood="serious", shot="close", board="Persecution · schools closed")
L("chrono", "Schools closed, and about seventeen million young people were sent to the countryside.", mood="serious", shot="close", board="~17 million youths sent to countryside", gap=0.8)
serious(False)
L("chrono", "And everywhere, Mao. Portraits, songs, badges, and the Little Red Book of his quotations. A cult of personality.", mood="teach", shot="close", board="Cult of personality: Little Red Book")
L("tara", "If the leader seems perfect, questioning him feels like a crime.", mood="thinking", shot="close")
L("chrono", "In Mao's China, it often was. Mao died in nineteen seventy six.", mood="serious", shot="close", gap=0.5)
L("chrono", "How do historians judge Mao? The Party's nineteen eighty one verdict is often summed up as, seventy percent right, thirty percent wrong.", mood="teach", shot="close", boardClear=True, board="1981 CCP verdict: '70% right, 30% wrong'")
L("chrono", "Historians like Frank Dikötter call the famine a man-made catastrophe. Others also weigh unity, land for peasants and rising literacy.", mood="teach", shot="close", board="Historians: catastrophe vs achievements")
L("chrono", "Weigh both sides, then judge. And ask who wrote the verdict, and why.", mood="teach", shot="close")

confess("chrono", "CHRONO · 950 Years Old · Recap Hourglass")
L("chrono", "Recap. First. Crisis. Humiliation, the Qing's fall in nineteen eleven, warlords, invasion.", mood="teach", boardClear=True, board="1. Crisis: humiliation, 1911, warlords")
L("chrono", "Second. Mao won the peasants, and the Long March became a legend.", mood="teach", board="2. Peasants + the Long March legend")
L("chrono", "Third. The corrupt Nationalists lost. People's Republic, nineteen forty nine.", mood="teach", board="3. Weak GMD falls · PRC 1 Oct 1949")
L("chrono", "Fourth. The Great Leap Forward. False reports, and a famine that killed tens of millions.", mood="teach", board="4. Great Leap → famine, tens of millions")
L("chrono", "And finally. The Cultural Revolution, the cult of Mao, and a verdict still debated.", mood="teach", board="5. Cultural Revolution · cult · debate", gap=0.6)

scene("living", [("tara", 260), ("mum", 560), ("dad", 840)])
L("dad", "Revised report. Plants, two. Recycling, one bag. Woks, zero. Tans, still winning.", mood="sad", shot="close", prop="tablet")
L("mum", "Thank you for the real numbers. We'll buy a new wok. On sale.", mood="happy", shot="close")
L("tara", "Honest numbers and realistic targets. Who are you?", mood="shock", shot="close")
L("dad", "I'll take it.", mood="smug", shot="close")
sfx("ding")
L("chrono", "Nobody melt me down. I'm an antique.", mood="bored", shot="wide", offstage=True, gap=0.8)

